import type { FC, MouseEvent } from 'react';
import { useRef } from 'react';
import { Link } from 'react-router-dom';
import { motion, useMotionValue, useSpring, useTransform } from 'framer-motion';
import { ArrowRight } from 'lucide-react';
import type { ToolMeta } from '@/data/tools';
import { getToolPath } from '@/data/tools';

interface ToolCardProps {
  tool: ToolMeta;
  index: number;
}

const ToolCard: FC<ToolCardProps> = ({ tool, index }) => {
  const Icon = tool.icon;
  const isAvailable = tool.status === 'available';

  // Same pointer-tracked 3D tilt used on the Projects/Certifications cards.
  const cardRef = useRef<HTMLDivElement>(null);
  const pointerX = useMotionValue(0);
  const pointerY = useMotionValue(0);
  const springConfig = { stiffness: 220, damping: 20, mass: 0.6 };
  const rotateX = useSpring(useTransform(pointerY, [-0.5, 0.5], [10, -10]), springConfig);
  const rotateY = useSpring(useTransform(pointerX, [-0.5, 0.5], [-10, 10]), springConfig);
  const translateY = useSpring(useTransform(pointerY, [-0.5, 0.5], [6, -6]), springConfig);

  const handleMouseMove = (event: MouseEvent<HTMLDivElement>) => {
    const rect = cardRef.current?.getBoundingClientRect();
    if (!rect) return;
    pointerX.set((event.clientX - rect.left) / rect.width - 0.5);
    pointerY.set((event.clientY - rect.top) / rect.height - 0.5);
  };

  const handleMouseLeave = () => {
    pointerX.set(0);
    pointerY.set(0);
  };

  const content = (
    <div
      className={`glass-panel group relative h-full p-6 flex flex-col transition-shadow duration-300 ${
        isAvailable ? 'hover:shadow-glow cursor-pointer' : 'opacity-60 cursor-not-allowed'
      }`}
    >
      <div className="flex items-start justify-between mb-4">
        <div className="w-11 h-11 rounded-full bg-accent/10 flex items-center justify-center">
          <Icon className="w-5 h-5 text-accent" />
        </div>
        {!isAvailable && (
          <span className="px-2.5 py-1 text-xs rounded-full bg-background/50 text-muted-foreground border border-border font-medium">
            Coming soon
          </span>
        )}
      </div>

      <h2 className="text-lg font-semibold mb-2 text-foreground group-hover:text-accent transition-colors tracking-tight">
        {tool.title}
      </h2>
      <p className="text-sm text-muted-foreground leading-relaxed mb-4 flex-1">
        {tool.description}
      </p>

      <div className="flex items-center justify-between">
        <div className="flex flex-wrap gap-1.5">
          {tool.tags.map((tag) => (
            <span
              key={tag}
              className="px-2 py-0.5 text-xs rounded-full bg-background/50 text-accent border border-accent/30 font-medium"
            >
              {tag}
            </span>
          ))}
        </div>
        {isAvailable && (
          <ArrowRight className="w-4 h-4 text-accent opacity-0 -translate-x-1 group-hover:opacity-100 group-hover:translate-x-0 transition-all duration-200" />
        )}
      </div>
    </div>
  );

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.4, delay: index * 0.08 }}
      style={{ perspective: 1000 }}
      className="h-full"
    >
      {isAvailable ? (
        <motion.div
          ref={cardRef}
          onMouseMove={handleMouseMove}
          onMouseLeave={handleMouseLeave}
          style={{ rotateX, rotateY, y: translateY, transformStyle: 'preserve-3d' }}
          whileHover={{ scale: 1.03 }}
          transition={{ type: 'spring', stiffness: 220, damping: 20 }}
          className="h-full"
        >
          <Link to={getToolPath(tool.slug)} aria-label={`Open ${tool.title}`} className="block h-full">
            {content}
          </Link>
        </motion.div>
      ) : (
        <div aria-disabled="true" className="h-full">
          {content}
        </div>
      )}
    </motion.div>
  );
};

export default ToolCard;
